add_action( 'woocommerce_thankyou', 'perfectpixel_products_on_thank_you_page', 20 );

function perfectpixel_products_on_thank_you_page( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order || $order->has_status( 'failed' ) ) {
		return;
	}
	echo '<section class="perfectpixel-thankyou-products"><h2>' . esc_html( '{{thankyou_products_title}}' ) . '</h2>';
	echo do_shortcode( '{{thankyou_products_shortcode}}' ); // phpcs:ignore WordPress.Security.EscapeOutput
	echo '</section>';
}
